using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;
public class CP6Probe:MonoBehaviour {
 [Serializable]public class Row{public string name,status,detail;}[Serializable]class Receipt{public string layer,error;public Row[] rows;}[Serializable]class Legacy{public int weapon;public bool skill,accepted;public int spawns;public float loss,cooldown;}
 readonly List<Row> rows=new List<Row>();readonly List<Legacy> legacy=new List<Legacy>();public static bool Done;public static int Code;public bool save,extra;string root;public string Root=>root;bool finished;int spawns;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-cp06-a")<0)return;var o=new GameObject("CP06 isolated probe");DontDestroyOnLoad(o);var probe=o.AddComponent<CP6Probe>();probe.save=Array.IndexOf(Environment.GetCommandLineArgs(),"-cp06-save")>=0;probe.extra=Array.IndexOf(Environment.GetCommandLineArgs(),"-cp06-extra")>=0;}
 public void Check(string n,bool b,string d){rows.Add(new Row{name=n,status=b?"PASS":"FAIL",detail=d});File.AppendAllText(root+"/progress.jsonl",JsonUtility.ToJson(rows.Last())+"\n");}
 IEnumerator Start(){root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);AdventureProjectile.Observed+=Projectile;var stack=new Stack<IEnumerator>();stack.Push(save?(IEnumerator)typeof(CombatEnemy).Assembly.GetType("CP6Save").GetMethod("Run").Invoke(null,new object[]{this}):extra?(IEnumerator)typeof(CombatEnemy).Assembly.GetType("CP6Extra").GetMethod("Run").Invoke(null,new object[]{this}):Run());while(stack.Count>0){bool more;object v=null;try{more=stack.Peek().MoveNext();if(more)v=stack.Peek().Current;}catch(Exception e){End(e.ToString());yield break;}if(!more){stack.Pop();continue;}if(v is IEnumerator sub){stack.Push(sub);continue;}yield return v;}End(null);}
 void Projectile(AdventureProjectile.Observation o){if(o.stage=="spawn")spawns++;File.AppendAllText(root+"/projectiles.jsonl",JsonUtility.ToJson(new ProjectileRow{stage=o.stage,attack=o.projectile.AttackId,shot=o.projectile.ShotIndex,from=o.from,to=o.to,collider=o.collider==null?"":o.collider.name})+"\n");}
 [Serializable]class ProjectileRow{public string stage,collider;public long attack;public int shot;public Vector3 from,to;}
 public IEnumerator Wait(Func<bool> predicate,float time){float end=Time.realtimeSinceStartup+time;while(!predicate()&&Time.realtimeSinceStartup<end)yield return null;}
 public IEnumerator Reopen(){var old=CP05Training.Instance.Hero;CP05Training.Instance.RequestRestart();yield return Wait(()=>CP05Training.Instance.Hero!=old&&!CP05Training.Instance.Restarting,5);yield return null;yield return null;}
 public void Setup(int w){var h=CP05Training.Instance.Hero;var e=CP05Training.Instance.Enemies[0];CP05Training.Instance.Enemies[1].gameObject.SetActive(false);e.enabled=false;var cc=e.GetComponent<CharacterController>();cc.enabled=false;e.transform.position=h.transform.position+Vector3.forward*((w>=2)?3:1.5f);cc.enabled=true;h.transform.rotation=Quaternion.identity;var c=h.GetComponent<AdventureCombat>();c.Gear.SelectMain(c.Gear.items.First(x=>(int)x.type==w&&x.InBag));var cam=h.cameraTransform.GetComponent<OrbitCamera>();cam.enabled=false;cam.transform.position=h.transform.position+new Vector3(0,3,-5);cam.transform.LookAt(e.transform.position+Vector3.up);CombatAssistOptions.Ranged=CombatAssistOptions.Melee=false;PlayerInput.Focus(true);}
 IEnumerator Run(){yield return Wait(()=>CP05Training.Instance?.Hero!=null,15);if(CP05Training.Instance?.Hero==null)throw new Exception("Training absent");
 for(int w=0;w<4;w++)for(int s=0;s<2;s++){yield return Reopen();Setup(w);yield return new WaitForSeconds(.3f);var h=CP05Training.Instance.Hero;var c=h.GetComponent<AdventureCombat>();var e=CP05Training.Instance.Enemies[0];float before=e.Health.Current;spawns=0;bool accepted=s==0?c.Strike():c.UseSkill();float cd=c.SkillRemaining;yield return new WaitForSeconds(1.1f);legacy.Add(new Legacy{weapon=w,skill=s==1,accepted=accepted,spawns=spawns,loss=before-e.Health.Current,cooldown=cd});Check("legacy-"+w+"-"+s,accepted&&e.Health.Current<before,"real old attack -> physical collision -> HP loss; no Damage injection");}
 File.WriteAllText(root+"/legacy.json",JsonUtility.ToJson(new LegacyRows{rows=legacy.ToArray()},true));var type=typeof(AdventureCombat).Assembly.GetType("WeaponSkillExpansion");for(int w=0;w<4;w++)for(int slot=1;slot<=2;slot++)Check("expanded-defined-"+w+"-"+slot,type!=null,"independent implemented skill required");
 if(type!=null)yield return Expanded(type);
 }
 [Serializable]class LegacyRows{public Legacy[] rows;}
 IEnumerator Expanded(Type type){var runner=typeof(CombatEnemy).Assembly.GetType("CP6Expanded");if(runner==null)throw new Exception("Missing isolated expansion driver");yield return (IEnumerator)runner.GetMethod("Run").Invoke(null,new object[]{this});}
 public void Capture(string name){StartCoroutine(CaptureFrame(name));}
 IEnumerator CaptureFrame(string name){yield return new WaitForEndOfFrame();var image=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(root+"/"+name+".png",image.EncodeToPNG());Destroy(image);}
 void End(string error){if(finished)return;finished=true;AdventureProjectile.Observed-=Projectile;if(error!=null)Check("probe-exception",false,error);Code=rows.Any(r=>r.status=="FAIL")?1:0;File.WriteAllText(root+"/probe.json",JsonUtility.ToJson(new Receipt{layer=Application.isEditor?"Editor controlled API":"nondevelopment Player controlled API",error=error,rows=rows.ToArray()},true));Done=true;if(!Application.isEditor)Application.Quit(Code);}
}
